type Client = { id: string; name: string; industry: string; taxNumber: string; contact: string; acceptance: string; independenceChecked: boolean; status: 'نشط' | 'مؤرشف'; createdAt: string };
type Engagement = { id: string; clientId: string; year: string; type: string; framework: string; partner: string; status: string; materiality: string; openedAt: string; scope?: string; plannedStart?: string; plannedEnd?: string; feeJod?: string; team?: string; independenceStatus?: string; conflictCheck?: string; declarationDate?: string };
type Risk = { id: string; engagementId: string; title: string; area: string; likelihood: string; impact: string; response: string; status: string };
type WorkpaperVersion = { version: number; at: string; actor: string; action: string; status: string; note: string };
type Workpaper = { id: string; engagementId: string; ref: string; title: string; area: string; preparer: string; reviewer: string; status: string; conclusion: string; updatedAt: string; procedure?: string; tickmarks?: string; reviewNotes?: string; version?: number; history?: WorkpaperVersion[] };
type Finding = { id: string; engagementId: string; title: string; criteria: string; condition: string; effect: string; recommendation: string; severity: string; status: string };
type Evidence = { id: string; engagementId: string; title: string; type: string; reference: string; workpaperRef: string; notes: string; addedAt: string };
type TBRow = { id: string; engagementId: string; code: string; name: string; openingDebit: number; openingCredit: number; debit: number; credit: number; closingDebit: number; closingCredit: number; source: string };
type AuditEvent = { id: string; at: string; action: string; entity: string; details: string; engagementId?: string }; 
type Module = 'dashboard'|'clients'|'engagements'|'planning'|'trial-balance'|'workpapers'|'evidence'|'findings'|'reports'|'reconciliation'|'settings';
type DB = { clients: Client[]; engagements: Engagement[]; risks: Risk[]; workpapers: Workpaper[]; findings: Finding[]; evidence: Evidence[]; trialBalance: TBRow[]; auditLog: AuditEvent[]; completionChecks: Record<string, boolean>; };
