  const engagement:Engagement={id:engagementId,clientId,year:String(new Date().getFullYear()-1),type:'تدقيق سنوي',framework:'IFRS for SMEs',partner:'شريك تجريبي',status:'التخطيط',materiality:'12000',openedAt:today(),scope:'بيانات تدريبية لاختبار سير العمل فقط',plannedStart:today(),plannedEnd:'',feeJod:'2500',team:'مدقق أول تجريبي، مساعد تجريبي',independenceStatus:'مكتمل',conflictCheck:'لا يوجد تعارض معروف',declarationDate:today()};
  const risk:Risk={id:riskId,engagementId,title:'مخاطر الاعتراف بالإيراد قرب نهاية الفترة',area:'الإيرادات',likelihood:'متوسط',impact:'مرتفع',response:'اختبار عينة من فواتير آخر وآول الفترة وربطها بمستندات التسليم',status:'مفتوح'};
  const workpaper:Workpaper={id:workpaperId,engagementId,ref:'WP-REV-001',title:'اختبار عينة من إيرادات المبيعات',area:'الإيرادات',preparer:'مساعد تجريبي',reviewer:'مراجع تجريبي',status:'بانتظار المراجعة',conclusion:'عينة تدريبية؛ يلزم توثيق الاستنتاج بعد فحص المستندات.',procedure:'اختيار عينة من قيود المبيعات وربطها بالفواتير وإشعارات التسليم.',tickmarks:'✓ تم الربط في المثال التجريبي',reviewNotes:'تحقق من تغطية الأيام القريبة من نهاية الفترة.',version:1,history:[{version:1,at:now,actor:'مساعد تجريبي',action:'إنشاء ورقة العمل',status:'مسودة',note:'سجل توضيحي'}],updatedAt:today()};
  const finding:Finding={id:findingId,engagementId,title:'مثال تدريبي: مستند تسليم غير مرفق',criteria:'سياسة توثيق المبيعات',condition:'في السجل التدريبي، لم يُرفق مستند التسليم مع إحدى العمليات.',effect:'احتمال ضعف كفاية أدلة الإثبات إذا حدث ذلك في ملف حقيقي.',recommendation:'ربط مستند التسليم بالعملية وإعادة تقييم العينة.',severity:'متوسطة',status:'مفتوحة'};
